    await page.reload();
    await page.getByRole('button', { name: /^Search/ }).focus();
    await page.screenshot({ path: `${OUT}/header-${theme}.png`, clip: { x: 0, y: 0, width: 1280, height: 64 } });
    await page.keyboard.press('ControlOrMeta+k');
    await page.getByRole('combobox', { name: 'Search DataQ' }).fill('ord');
    await page.getByRole('option').first().waitFor();
    await page.screenshot({ path: `${OUT}/palette-${theme}.png` });
    await page.getByRole('combobox', { name: 'Search DataQ' }).fill('zzzz-nothing');
    await page.getByRole('status').filter({ hasText: 'No matches' }).waitFor();
    await page.screenshot({ path: `${OUT}/palette-empty-${theme}.png` });
  });
}

