1	import { SearchOutlined } from '@ant-design/icons';
2	import { Button, Input, type InputRef, Typography } from 'antd';
3	import {
4	  type CSSProperties,
5	  type KeyboardEvent as ReactKeyboardEvent,
6	  useCallback,
7	  useEffect,
8	  useId,
9	  useMemo,
10	  useRef,
11	  useState,
12	} from 'react';
13	import { useNavigate } from 'react-router-dom';
14	
15	import {
16	  SEARCH_GROUPS,
17	  search,
18	  type SearchGroupName,
19	  type SearchHit,
20	  type SearchResponse,
21	} from '../../api/search';
22	import { IS_DEMO } from '../../demo/flag';
23	import { fetchFailure } from '../../utils/errors';
24	import { formatTimestamp } from '../results/resultsFormat';
25	import { Modal } from './Modal';
26	
27	const GROUP_LABELS: Record<SearchGroupName, string> = {
28	  suites: 'Suites',
29	  checks: 'Checks',
30	  connections: 'Connections',
31	  runs: 'Runs',
32	};
33	
34	export const DEMO_SEARCH_MESSAGE = 'Search is not part of the read-only demo.';
35	const DEBOUNCE_MS = 200;
36	
37	const isMac = typeof navigator !== 'undefined' && /Mac|iPhone|iPad/.test(navigator.userAgent);
38	/** The shortcut as the user's keyboard writes it. */
39	const SHORTCUT_LABEL = isMac ? '⌘K' : 'Ctrl K';
40	
41	type Phase =
42	  | { kind: 'idle' }
43	  | { kind: 'loading' }
44	  | { kind: 'ok'; data: SearchResponse }
45	  | { kind: 'error'; message: string };
46	
47	interface Option {
48	  id: string;
49	  group: SearchGroupName;
50	  hit: SearchHit;
51	}
52	
53	function flatten(data: SearchResponse, prefix: string): Option[] {
54	  return SEARCH_GROUPS.flatMap((group) =>
55	    data.groups[group].map((hit) => ({ id: `${prefix}-${group}-${hit.id}`, group, hit })),
56	  );
57	}
58	
59	function hitDescription(group: SearchGroupName, hit: SearchHit): string | null {
60	  if (group === 'runs') {
61	    const when = hit.when ? formatTimestamp(hit.when) : null;
62	    return [hit.sublabel, when].filter(Boolean).join(' · ') || null;
63	  }
64	  return hit.sublabel;
65	}
66	
67	/**
68	 * Global search (⌘K / Ctrl K): the header's search button and the dialog it opens, mounted once
69	 * in the app shell. Typing searches suites, checks, connections and runs by name; arrow keys move
70	 * through the results, Enter opens the highlighted one, Escape closes. Focus returns to whatever
71	 * had it when the palette opened.
72	 */
73	export function CommandPalette({ compact = false }: { compact?: boolean }) {
74	  const navigate = useNavigate();
75	  const baseId = useId();
76	  const listId = `${baseId}-list`;
77	  const [open, setOpen] = useState(false);
78	  const [query, setQuery] = useState('');
79	  const [phase, setPhase] = useState<Phase>({ kind: 'idle' });
80	  const [active, setActive] = useState(0);
81	  const inputRef = useRef<InputRef>(null);
82	  const triggerRef = useRef<HTMLButtonElement>(null);
83	  const openerRef = useRef<HTMLElement | null>(null);
84	  const requestSeq = useRef(0);
85	
86	  const openPalette = useCallback(() => {
87	    openerRef.current = document.activeElement as HTMLElement | null;
88	    setOpen(true);
89	  }, []);
90	
91	  const closePalette = useCallback(() => {
92	    setOpen(false);
93	    requestSeq.current += 1;
94	    setQuery('');
95	    setPhase({ kind: 'idle' });
96	    setActive(0);
97	    const opener = openerRef.current;
98	    const target = opener && opener.isConnected && opener !== document.body ? opener : null;
99	    // After the dialog has let go of focus, not before.
100	    requestAnimationFrame(() => (target ?? triggerRef.current)?.focus());
101	  }, []);
102	
103	  useEffect(() => {
104	    const onKeyDown = (event: KeyboardEvent) => {
105	      if ((event.metaKey || event.ctrlKey) && !event.altKey && event.key.toLowerCase() === 'k') {
106	        event.preventDefault();
107	        if (open) closePalette();
108	        else openPalette();
109	      }
110	    };
111	    window.addEventListener('keydown', onKeyDown);
112	    return () => window.removeEventListener('keydown', onKeyDown);
113	  }, [open, openPalette, closePalette]);
114	
115	  // The phase follows the keystroke; the request itself is debounced and abortable, and a late
116	  // answer to an earlier query is dropped.
117	  const onQueryChange = (value: string) => {
118	    setQuery(value);
119	    requestSeq.current += 1;
120	    const term = value.trim();
121	    if (!term) setPhase({ kind: 'idle' });
122	    else if (IS_DEMO) setPhase({ kind: 'error', message: DEMO_SEARCH_MESSAGE });
123	    else setPhase({ kind: 'loading' });
124	  };
125	
126	  useEffect(() => {
127	    const term = query.trim();
128	    if (!open || !term || IS_DEMO) return;
129	    const seq = requestSeq.current;
130	    const controller = new AbortController();
131	    const timer = window.setTimeout(() => {
132	      search(term, controller.signal)
133	        .then((data) => {
134	          if (seq !== requestSeq.current) return;
135	          setPhase({ kind: 'ok', data });
136	          setActive(0);
137	        })
138	        .catch((err: unknown) => {
139	          if (seq !== requestSeq.current || controller.signal.aborted) return;
140	          setPhase({ kind: 'error', message: fetchFailure(err, 'Search failed').message });
141	        });
142	    }, DEBOUNCE_MS);
143	    return () => {
144	      window.clearTimeout(timer);
145	      controller.abort();
146	    };
147	  }, [open, query]);
148	
149	  const options = useMemo(
150	    () => (phase.kind === 'ok' ? flatten(phase.data, baseId) : []),
151	    [phase, baseId],
152	  );
153	  const activeOption = options[active];
154	
155	  const choose = (option: Option) => {
156	    closePalette();
157	    navigate(option.hit.href);
158	  };
159	
160	  const onInputKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
161	    if (event.key === 'ArrowDown' && options.length) {
162	      event.preventDefault();
163	      setActive((i) => (i + 1) % options.length);
164	    } else if (event.key === 'ArrowUp' && options.length) {
165	      event.preventDefault();
166	      setActive((i) => (i - 1 + options.length) % options.length);
167	    } else if (event.key === 'Enter' && activeOption) {
168	      event.preventDefault();
169	      choose(activeOption);
170	    } else if (event.key === 'Escape') {
171	      event.preventDefault();
172	      closePalette();
173	    }
174	  };
175	
176	  useEffect(() => {
177	    if (!activeOption) return;
178	    document.getElementById(activeOption.id)?.scrollIntoView?.({ block: 'nearest' });
179	  }, [activeOption]);
180	
181	  const status = statusText(phase, query, options.length);
182	
183	  return (
184	    <>
185	      <Button
186	        ref={triggerRef}
187	        type="text"
188	        icon={<SearchOutlined aria-hidden />}
189	        aria-label={compact ? `Search (${SHORTCUT_LABEL})` : undefined}
190	        aria-keyshortcuts={isMac ? 'Meta+K' : 'Control+K'}
191	        onClick={openPalette}
192	        style={{ color: 'var(--dq-muted)' }}
193	      >
194	        {!compact && (
195	          <>
196	            Search
197	            <kbd
198	              aria-hidden
199	              style={{
200	                marginInlineStart: 8,
201	                padding: '0 6px',
202	                borderRadius: 4,
203	                border: '1px solid var(--dq-border)',
204	                background: 'var(--dq-canvas)',
205	                fontSize: 12,
206	                fontFamily: 'inherit',
207	              }}
208	            >
209	              {SHORTCUT_LABEL}
210	            </kbd>
211	          </>
212	        )}
213	      </Button>
214	      {open && (
215	        <Modal
216	          open
217	          onCancel={closePalette}
218	          title={<span className="dq-sr-only">Search DataQ</span>}
219	          footer={null}
220	          closable={false}
221	          focusable={{ focusTriggerAfterClose: false }}
222	          width={640}
223	          styles={{ header: { marginBottom: 0 }, body: { paddingTop: 4 } }}
224	          afterOpenChange={(visible) => {
225	            if (visible) inputRef.current?.focus();
226	          }}
227	        >
228	          <Input
229	            ref={inputRef}
230	            autoFocus
231	            size="large"
232	            value={query}
233	            onChange={(e) => onQueryChange(e.target.value)}
234	            onKeyDown={onInputKeyDown}
235	            placeholder="Search suites, checks, connections and runs"
236	            prefix={<SearchOutlined aria-hidden style={{ color: 'var(--dq-muted)' }} />}
237	            allowClear
238	            autoComplete="off"
239	            role="combobox"
240	            aria-label="Search DataQ"
241	            aria-expanded={options.length > 0}
242	            aria-controls={listId}
243	            aria-autocomplete="list"
244	            aria-activedescendant={activeOption?.id}
245	            aria-describedby={`${baseId}-status`}
246	          />
247	          <ul
248	            id={listId}
249	            role="listbox"
250	            aria-label="Search results"
251	            style={{
252	              listStyle: 'none',
253	              margin: '12px 0 0',
254	              padding: 0,
255	              maxHeight: '50vh',
256	              overflowY: 'auto',
257	            }}
258	          >
259	            {phase.kind === 'ok' &&
260	              SEARCH_GROUPS.filter((group) => phase.data.groups[group].length > 0).map((group) => (
261	                <li key={group} role="presentation">
262	                  <Typography.Text
263	                    type="secondary"
264	                    role="presentation"
265	                    style={{
266	                      display: 'block',
267	                      fontSize: 12,
268	                      textTransform: 'uppercase',
269	                      letterSpacing: 0.4,
270	                      padding: '10px 8px 4px',
271	                    }}
272	                  >
273	                    {GROUP_LABELS[group]}
274	                  </Typography.Text>
275	                  <ul role="group" aria-label={GROUP_LABELS[group]} style={listReset}>
276	                    {options
277	                      .filter((option) => option.group === group)
278	                      .map((option) => {
279	                        const selected = option.id === activeOption?.id;
280	                        const description = hitDescription(group, option.hit);
281	                        return (
282	                          <li
283	                            key={option.id}
284	                            id={option.id}
285	                            role="option"
286	                            aria-selected={selected}
287	                            onMouseDown={(e) => e.preventDefault()}
288	                            onClick={() => choose(option)}
289	                            onMouseEnter={() => setActive(options.indexOf(option))}
290	                            style={{
291	                              display: 'flex',
292	                              justifyContent: 'space-between',
293	                              gap: 12,
294	                              padding: '8px 10px',
295	                              borderRadius: 6,
296	                              cursor: 'pointer',
297	                              background: selected ? 'var(--dq-selected-bg)' : undefined,
298	                              color: 'var(--dq-ink)',
299	                            }}
300	                          >
301	                            <span style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>
302	                              {option.hit.label}
303	                            </span>
304	                            {description && (
305	                              <Typography.Text type="secondary" style={{ whiteSpace: 'nowrap' }}>
306	                                {description}
307	                              </Typography.Text>
308	                            )}
309	                          </li>
310	                        );
311	                      })}
312	                  </ul>
313	                  {phase.data.truncated_groups.includes(group) && (
314	                    <Typography.Text
315	                      type="secondary"
316	                      role="presentation"
317	                      style={{ display: 'block', fontSize: 12, padding: '2px 10px 6px' }}
318	                    >
319	                      More {GROUP_LABELS[group].toLowerCase()} match — keep typing to narrow it.
320	                    </Typography.Text>
321	                  )}
322	                </li>
323	              ))}
324	          </ul>
325	          <div
326	            id={`${baseId}-status`}
327	            role="status"
328	            aria-live="polite"
329	            style={{ marginTop: 8, color: 'var(--dq-muted)', fontSize: 12, minHeight: 18 }}
330	          >
331	            {status}
332	          </div>
333	        </Modal>
334	      )}
335	    </>
336	  );
337	}
338	
339	const listReset: CSSProperties = { listStyle: 'none', margin: 0, padding: 0 };
340	
341	function statusText(phase: Phase, query: string, count: number): string {
342	  switch (phase.kind) {
343	    case 'idle':
344	      return query.trim() ? '' : 'Type to search. ↑↓ to move, Enter to open, Esc to close.';
345	    case 'loading':
346	      return 'Searching…';
347	    case 'error':
348	      return phase.message;
349	    case 'ok':
350	      return count === 0
351	        ? `No matches for “${phase.data.query}”.`
352	        : `${count} ${count === 1 ? 'result' : 'results'}. ↑↓ to move, Enter to open.`;
353	  }
354	}
